@@ -0,0 +1,13 @@
+import { createEventCard } from './event-card.js';
+
+// Builds a value per event, then orders them by start time (stable on ties).
+export function mapChronologically(events, build) {
+  return events
+    .map((event, index) => ({ value: build(event), index, time: new Date(event.startsAt).getTime() }))
+    .sort((a, b) => a.time - b.time || a.index - b.index)
+    .map(({ value }) => value);
+}
+
+export function buildAgenda(events) {
+  return mapChronologically(events, createEventCard);
+}

